/**
 * Deciding device keys: trust, distrust, adoption and session reset (ADR 0006 §6).
 *
 * Every key here is generated by `@curlew/omemo` and every JID is synthetic. The storage is a
 * real `SecretStoreOmemoStorage` on an in-memory database rather than `MemoryOmemoStorage`,
 * because a pending key change is stored in a namespace only the adapter has — and what these
 * cases are about is precisely that a decision lands on the key the person compared.
 *
 * The sessions are stubs: nothing here steps a ratchet, and what the cases check is whether one
 * exists at all. A round trip through the real thing is `omemo-send.test.ts`'s business.
 *
 * The property most of them exist for: nothing writes `verified` or `distrusted` except a typed
 * fingerprint that matched exactly one device, and a reset never forgets a decision.
 */

import { describe, expect, it } from '@gjsify/unit';

import {
  fingerprint,
  formatFingerprint,
  generateKeyPair,
  LEGACY_PROFILE,
  MemoryOmemoStorage,
  toBase64,
  type DeviceAddress,
  type SessionRecord,
} from '@curlew/omemo';
import { SecretStore } from '@curlew/store';
import {
  noteBundleIdentity,
  noteIdentity,
  resetSessions,
  SecretStoreOmemoStorage,
  setTrustByFingerprint,
  summarizeDevices,
  type TrustStorage,
} from '@curlew/xmpp';

const BOB = 'bob@example.org';
const CAROL = 'carol@example.org';
const START = new Date('2026-01-01T00:00:00Z');
const LATER = new Date('2026-02-01T00:00:00Z');

/** A fresh account file in memory. */
function storage(): SecretStoreOmemoStorage {
  return new SecretStoreOmemoStorage(SecretStore.open(':memory:'));
}

/** A ratchet-shaped placeholder: these cases ask whether a session is there, never what it says. */
function stubSession(): SessionRecord {
  const zero = toBase64(new Uint8Array(32));
  return {
    version: LEGACY_PROFILE.version,
    ourIdentityKey: zero,
    theirIdentityKey: zero,
    ratchet: { rootKey: zero, ownRatchetPrivateKey: zero, previousSendingLength: 0, skipped: [] },
  };
}

/** Put a key under one device id and hand back what a person would read off `omemo devices`. */
async function known(
  store: TrustStorage,
  address: DeviceAddress,
  publicKey: Uint8Array,
): Promise<{ fingerprint: string; formatted: string }> {
  await noteIdentity(store, address, publicKey, START);
  return { fingerprint: fingerprint(publicKey), formatted: formatFingerprint(publicKey) };
}

export default async function omemoTrust(): Promise<void> {
  await describe('deciding one device key', async () => {
    await it('verifies the device whose fingerprint was typed, and only that one', async () => {
      const store = storage();
      const print = await known(store, { jid: BOB, deviceId: 1 }, generateKeyPair().publicKey);
      await known(store, { jid: BOB, deviceId: 2 }, generateKeyPair().publicKey);

      const result = await setTrustByFingerprint(store, BOB, print.fingerprint, 'verified', LATER);
      expect(result.kind).toBe('set');
      expect(result.kind === 'set' ? result.address.deviceId : 0).toBe(1);
      expect(result.kind === 'set' ? result.adopted : true).toBe(false);

      // BTBV decides a KEY, never a contact: device 2 is exactly where it was.
      const devices = await summarizeDevices(store, BOB);
      expect(devices.map((d) => `${String(d.deviceId)}:${d.trust}`).join(' ')).toBe('1:verified 2:blind');
    });

    await it('reads the fingerprint in whatever grouping it was given', async () => {
      const store = storage();
      const print = await known(store, { jid: BOB, deviceId: 7 }, generateKeyPair().publicKey);
      // What a person pastes out of another client: groups of eight, uppercase.
      const typed = print.formatted.toUpperCase();
      expect((await setTrustByFingerprint(store, BOB, typed, 'distrusted', LATER)).kind).toBe('set');
      expect((await summarizeDevices(store, BOB))[0].trust).toBe('distrusted');
    });

    await it('changes nothing when the typed text is not a fingerprint', async () => {
      const store = storage();
      await known(store, { jid: BOB, deviceId: 1 }, generateKeyPair().publicKey);
      expect((await setTrustByFingerprint(store, BOB, 'the roof is leaking', 'verified')).kind).toBe(
        'unparsable',
      );
      expect((await summarizeDevices(store, BOB))[0].trust).toBe('blind');
    });

    await it('changes nothing when no device of that contact carries the key', async () => {
      const store = storage();
      await known(store, { jid: BOB, deviceId: 1 }, generateKeyPair().publicKey);
      // A well-formed fingerprint of somebody else's device: the mistake of comparing the wrong
      // contact's key, which must not land on a device of this one.
      const stranger = fingerprint(generateKeyPair().publicKey);
      expect((await setTrustByFingerprint(store, BOB, stranger, 'verified')).kind).toBe('unknown');
      expect((await summarizeDevices(store, BOB))[0].trust).toBe('blind');
    });

    await it('refuses a fingerprint two devices of the contact share', async () => {
      const store = storage();
      const shared = generateKeyPair().publicKey;
      const print = await known(store, { jid: BOB, deviceId: 1 }, shared);
      await known(store, { jid: BOB, deviceId: 2 }, shared);
      const result = await setTrustByFingerprint(store, BOB, print.fingerprint, 'verified');
      expect(result.kind).toBe('ambiguous');
      expect(result.kind === 'ambiguous' ? result.count : 0).toBe(2);
      expect((await summarizeDevices(store, BOB)).every((d) => d.trust === 'blind')).toBe(true);
    });
  });

  await describe('a key that replaced the one we hold', async () => {
    await it('is parked beside the stored one instead of overwriting it', async () => {
      const store = storage();
      const address = { jid: BOB, deviceId: 3 };
      const old = await known(store, address, generateKeyPair().publicKey);
      const fresh = generateKeyPair().publicKey;

      const noted = await noteBundleIdentity(store, address, fresh, LATER);
      expect(noted.outcome).toBe('replaced');
      // Still the key we had, still blindly trusted: the send path refuses, it does not re-trust.
      expect(noted.record.trust).toBe('blind');
      expect((await store.loadIdentity(address))?.publicKey).toBe(noted.record.publicKey);

      const [summary] = await summarizeDevices(store, BOB);
      expect(summary.fingerprint).toBe(old.fingerprint);
      expect(summary.changed?.fingerprint).toBe(fingerprint(fresh));
      expect(summary.changed?.seenAt).toBe(LATER.toISOString());
    });

    await it('keeps the date it was first seen when the peer publishes it again', async () => {
      const store = storage();
      const address = { jid: BOB, deviceId: 3 };
      await known(store, address, generateKeyPair().publicKey);
      const fresh = generateKeyPair().publicKey;
      await noteBundleIdentity(store, address, fresh, LATER);
      await noteBundleIdentity(store, address, fresh, new Date('2026-03-01T00:00:00Z'));
      // "Since when" is the question a reader has; refreshing it would answer "just now" for ever.
      expect((await summarizeDevices(store, BOB))[0].changed?.seenAt).toBe(LATER.toISOString());
    });

    await it('is adopted by a decision about it, and takes the ratchet with it', async () => {
      const store = storage();
      const address = { jid: BOB, deviceId: 3 };
      await known(store, address, generateKeyPair().publicKey);
      await store.saveSession(address, stubSession());
      const fresh = generateKeyPair().publicKey;
      await noteBundleIdentity(store, address, fresh, LATER);

      const result = await setTrustByFingerprint(store, BOB, fingerprint(fresh), 'verified', LATER);
      expect(result.kind === 'set' ? result.adopted : false).toBe(true);
      // The ratchet was built against the key we no longer hold, so it goes with the decision.
      expect(result.kind === 'set' ? result.sessionDropped : false).toBe(true);
      expect(await store.loadSession(address)).toBe(undefined);

      const [summary] = await summarizeDevices(store, BOB);
      expect(summary.fingerprint).toBe(fingerprint(fresh));
      expect(summary.trust).toBe('verified');
      // The pending entry is gone with the decision: there is nothing left to compare.
      expect(summary.changed).toBe(undefined);
    });

    await it('leaves the pending key alone when the OLD one is the one decided', async () => {
      const store = storage();
      const address = { jid: BOB, deviceId: 3 };
      const old = await known(store, address, generateKeyPair().publicKey);
      const fresh = generateKeyPair().publicKey;
      await noteBundleIdentity(store, address, fresh, LATER);

      // Distrusting what we hold is a decision about the stored key, not about the new one.
      const result = await setTrustByFingerprint(store, BOB, old.fingerprint, 'distrusted', LATER);
      expect(result.kind === 'set' ? result.adopted : true).toBe(false);
      const [summary] = await summarizeDevices(store, BOB);
      expect(summary.trust).toBe('distrusted');
      expect(summary.changed?.fingerprint).toBe(fingerprint(fresh));
    });

    await it('records nothing on a storage without the trust namespace', async () => {
      // `MemoryOmemoStorage` is a plain `OmemoStorage`: the functions still run and still refuse
      // the device, they just have nowhere to park the key. That is stage 3's behaviour exactly.
      const store = new MemoryOmemoStorage();
      const address = { jid: BOB, deviceId: 3 };
      await noteIdentity(store, address, generateKeyPair().publicKey, START);
      const noted = await noteBundleIdentity(store, address, generateKeyPair().publicKey, LATER);
      expect(noted.outcome).toBe('replaced');
      expect((await summarizeDevices(store, BOB))[0].changed).toBe(undefined);
    });
  });

  await describe('resetting the sessions with a contact', async () => {
    await it('drops every ratchet and the cached device list, and keeps the decisions', async () => {
      const store = storage();
      const print = await known(store, { jid: BOB, deviceId: 1 }, generateKeyPair().publicKey);
      await known(store, { jid: BOB, deviceId: 2 }, generateKeyPair().publicKey);
      await setTrustByFingerprint(store, BOB, print.fingerprint, 'verified', LATER);
      await store.saveSession({ jid: BOB, deviceId: 1 }, stubSession());
      await store.saveSession({ jid: BOB, deviceId: 2 }, stubSession());
      await store.saveDeviceList(BOB, { deviceIds: [1, 2], fetchedAt: START.toISOString() });

      const result = await resetSessions(store, BOB);
      expect([...result.deviceIds].sort((a, b) => a - b).join(' ')).toBe('1 2');
      // Deleted rather than expired: a stale cached list is served when a refetch fails.
      expect(result.deviceList).toBe(true);
      expect(await store.loadDeviceList(BOB)).toBe(undefined);
      expect(await store.loadSession({ jid: BOB, deviceId: 1 })).toBe(undefined);

      // The whole point: a stuck ratchet says nothing about whose key it was built against, so a
      // reset that asked the person to compare a verified fingerprint again would be the bug.
      const devices = await summarizeDevices(store, BOB);
      expect(devices.map((d) => `${String(d.deviceId)}:${d.trust}`).join(' ')).toBe('1:verified 2:blind');
      expect(devices.every((d) => !d.session)).toBe(true);
    });

    await it('leaves the sessions with another contact where they are', async () => {
      const store = storage();
      await store.saveSession({ jid: BOB, deviceId: 1 }, stubSession());
      await store.saveSession({ jid: CAROL, deviceId: 1 }, stubSession());
      const result = await resetSessions(store, BOB);
      expect(result.deviceList).toBe(false);
      expect(await store.loadSession({ jid: CAROL, deviceId: 1 })).not.toBe(undefined);
    });
  });
}
